#include <algorithm>
#include <cmath>
#include <cstdint>
#include <iomanip>
#include <iostream>

int main() {
    int64_t capital = 0;  // dollars
    int days = 0;
    std::cin >> capital >> days;
    int64_t equity = capital * 100;  // money stays in ticks of $0.01, like the P&L
    int64_t peak = equity;
    int64_t max_dd = 0;
    double max_dd_pct = 0.0;
    double growth = 1.0;
    double sum_simple = 0.0;
    double sum_log = 0.0;
    std::cout << std::fixed;
    for (int day = 1; day <= days; ++day) {
        int64_t pnl = 0;  // one night's pnl_ticks()
        std::cin >> pnl;
        const int64_t start = equity;
        equity += pnl;
        const double simple = double(pnl) / start;               // (V1 - V0) / V0
        const double log_ret = std::log(double(equity) / start);  // log(V1 / V0)
        growth *= 1.0 + simple;
        sum_simple += simple;
        sum_log += log_ret;
        peak = std::max(peak, equity);
        const int64_t dd = peak - equity;  // how far below the best day so far
        if (dd > max_dd) {
            max_dd = dd;
            max_dd_pct = double(dd) / peak;
        }
        std::cout << "day " << std::setw(2) << day << "  equity " << std::setprecision(2) << std::setw(9) << equity / 100.0
                  << std::setprecision(3) << "  simple " << std::setw(6) << simple * 100 << "%  log " << std::setw(6)
                  << log_ret * 100 << "%  drawdown " << std::setprecision(2) << dd / 100.0 << '\n';
    }
    std::cout << std::setprecision(3);
    std::cout << "compounded " << (growth - 1) * 100 << "%, exp(sum of logs) - 1 " << (std::exp(sum_log) - 1) * 100
              << "%, sum of simple " << sum_simple * 100 << "%\n";
    std::cout << std::setprecision(2) << "max drawdown $" << max_dd / 100.0 << " (" << max_dd_pct * 100 << "% of the peak)\n";
    return 0;
}

