#include <cmath>
#include <cstdint>
#include <iomanip>
#include <iostream>
#include <string>
#include <vector>

struct Stats {  // Welford's running mean and variance
    long n = 0;
    double mean = 0.0;
    double m2 = 0.0;
    void add(double x) {
        ++n;
        const double d = x - mean;
        mean += d / n;
        m2 += d * (x - mean);
    }
    double stdev() const { return n > 1 ? std::sqrt(m2 / (n - 1)) : 0.0; }
};

void report(const std::string& name, const std::vector<int64_t>& pnl) {
    Stats days;
    double down_sq = 0.0;  // the sum of squared losing days
    int wins = 0;
    for (int64_t p : pnl) {
        days.add(double(p));
        if (p < 0) {
            down_sq += double(p) * p;
        }
        if (p > 0) {
            ++wins;
        }
    }
    const double year = std::sqrt(252.0);
    const double downside = std::sqrt(down_sq / days.n);  // every day counts, gains as 0
    std::cout << name << ": mean $" << days.mean / 100 << ", sd $" << days.stdev() / 100 << '\n';
    std::cout << "  sharpe " << days.mean / days.stdev() * year << ", sortino " << days.mean / downside * year
              << ", hit rate " << 100.0 * wins / days.n << "%, error +- " << std::sqrt(252.0 / days.n) << '\n';
}

int main() {
    std::string name;
    int n = 0;
    std::cout << std::fixed << std::setprecision(2);
    while (std::cin >> name >> n) {
        std::vector<int64_t> pnl(n);  // daily P&L in ticks
        for (int64_t& p : pnl) {
            std::cin >> p;
        }
        report(name, pnl);
    }
    return 0;
}

