#include <cstdint>
#include <cstdlib>
#include <iomanip>
#include <iostream>

struct Tick {
    int64_t ts_ns;
    int64_t bid_ticks, ask_ticks;
    int64_t bid_sz, ask_sz;
};

struct Imbalance {  // the pipeline's signal: lean toward the side that holds the size
    double threshold;
    int operator()(const Tick& t) const {
        const double imb = double(t.bid_sz - t.ask_sz) / (t.bid_sz + t.ask_sz);
        return imb > threshold ? 1 : (imb < -threshold ? -1 : 0);
    }
};

struct Costs {
    int64_t slip_ticks;   // each share fills this many ticks worse than the quote
    int64_t fee_per_100;  // broker and exchange fees, in ticks per 100 shares
};

template <typename Signal>
struct Strategy {  // the pipeline's strategy, now charged for trading
    Strategy(Signal s, int64_t l, Costs c) : signal(s), lot(l), costs(c) {}
    void on_tick(const Tick& t) {
        const int64_t qty = signal(t) * lot - position;
        if (qty != 0) {
            const int64_t shares = std::abs(qty);
            const int64_t px = qty > 0 ? t.ask_ticks : t.bid_ticks;  // cross the spread
            cash -= qty * px;
            traded += shares;
            notional += shares * px;
            slippage += shares * costs.slip_ticks;
            fees += shares * costs.fee_per_100 / 100;  // exact: every fill is a whole lot
        }
        position += qty;
        mark = position > 0 ? t.bid_ticks : t.ask_ticks;
    }
    int64_t gross() const { return cash + position * mark; }
    Signal signal;
    int64_t lot;
    Costs costs;
    int64_t position = 0, mark = 0, cash = 0;
    int64_t traded = 0, notional = 0, slippage = 0, fees = 0;  // traded in shares, the rest in ticks
};

int main() {
    int64_t capital = 0;  // dollars
    Costs costs{};
    int n = 0;
    std::cin >> capital >> costs.slip_ticks >> costs.fee_per_100 >> n;
    Strategy<Imbalance> s(Imbalance{0.5}, 100, costs);
    for (int i = 0; i < n; ++i) {
        Tick t{};
        std::cin >> t.ts_ns >> t.bid_ticks >> t.ask_ticks >> t.bid_sz >> t.ask_sz;
        s.on_tick(t);
    }
    const int64_t net = s.gross() - s.slippage - s.fees;
    std::cout << std::fixed << std::setprecision(2);
    std::cout << "traded " << s.traded << " shares, turnover " << s.notional / 100.0 / capital << "x\n";
    std::cout << "gross     " << std::setw(7) << s.gross() / 100.0 << '\n';
    std::cout << "slippage  " << std::setw(7) << -s.slippage / 100.0 << '\n';
    std::cout << "fees      " << std::setw(7) << -s.fees / 100.0 << '\n';
    std::cout << "net       " << std::setw(7) << net / 100.0 << '\n';
    std::cout << "per share: edge " << double(s.gross()) / s.traded << " ticks, costs "
              << double(s.slippage + s.fees) / s.traded << " ticks\n";
    return 0;
}

